mapper.select:
/** * selectCnnctChatReqstdList : isry.couns.mngr.taskwkaltmntmng.mapper.CnnctChatReqstdMapper : 잇는채팅 상담신청서 목록 조회 */ SELECT AA.INDEX_SN AS INDEX_SN /** 신청 번호 **/ , C##RG.DEC_B64(AA.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT /** 내담자 이름 **/ , TO_CHAR(AA.WRT_DT,'YYYY-MM-DD') AS WRT_DT /** 작성일 **/ , ( SELECT C##RG.DEC_B64(B2.FLNM_ENCPT) FROM SAA200 A2 , SCA100 B2 WHERE 1=1 AND A2.USER_ID = BB.CONSTT_ID AND A2.ENFSN_NO = B2.ENFSN_NO ) AS CONSTT_NM_ENCPT /**상담자 명**/ , AA.MNGR_IDNTY_YN AS MNGR_IDNTY_YN /** 관리자확인여부 **/ , BB.INDEX_SN AS INDEX_SN_150 , COUNT(*) OVER() AS TOTAL_COUNT FROM AYB140 AA /** 잇는 채팅 **/ , AYA150 BB /** 상담자배정 **/ WHERE 1=1 AND AA.DEL_YN = 'N'
AND AA.WRT_DT >= TO_DATE(#{startDate} || '000000' , 'YYYYMMDDHH24MISS')
AND AA.WRT_DT < TO_DATE(#{endDate} || '000000' , 'YYYYMMDDHH24MISS')+1
AND AA.INDEX_SN = #{indexSn}
AND C##RG.DEC_B64(AA.TRPR_NM_ENCPT) LIKE '%' || #{trprNm} || '%'
AND BB.BBSCTT_ESNTAL_NO (+) = AA.INDEX_SN AND BB.BBSCTT_TYPE_SE_CD (+)= '92' AND BB.DEL_YN (+) = 'N' ORDER BY 1 DESC OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY /** 페이징 처리 **/

/** * selectCnnctChatReqstdDetail : isry.couns.mngr.taskwkaltmntmng.mapper.CnnctChatReqstdMapper : 잇는채팅 상담신청서 상세 조회 */ SELECT AA.INDEX_SN AS INDEX_SN /** 색인일련번호 **/ , AA.ATFINO AS ATFINO /** 파일첨부 **/ , TO_CHAR(AA.WRT_DT,'YYYY-MM-DD') AS WRT_DT /** 신청일 **/ , C##RG.DEC_B64(AA.TRPR_NM_ENCPT) AS TRPR_NM /** 성명 **/ , C1.CMMNS_CD_VALUE_NM AS APLCNT_SXDC_SE_CD /** 성별 **/ , SUBSTR(AA.BRTH_YMD, 1, 4)||'-'||SUBSTR(AA.BRTH_YMD, 5, 2)||'-'||SUBSTR(AA.BRTH_YMD, 7, 2) AS BRTH_YMD /** 생년월일 **/ , C##RG.DEC_B64(AA.TRPR_MBL_TELNO_ENCPT) AS TRPR_MBL_TELNO /** 연락처 **/ , AA.TRPR_ADDR AS TRPR_ADDR /** 주소 **/ , AA.NOW_AGE AS NOW_AGE /** 나이 **/ , C##RG.DEC_B64(AA.TRPR_EML_ADDR_ENCPT) AS TRPR_EML_ADDR /** 이메일 **/ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'YNGBGS_STTS_LCLAS_SE_CD' AND A1.CMMNS_CD_VALUE = AA.YNGBGS_STTS_LCLAS_SE_CD ) AS ITNEUN_CHTT_SCHULW_STTS_SE_CD /** 학업상태구분코드 **/ , C2.CMMNS_CD_VALUE_NM AS ACBG_SE_CD /** 학교구분코드 **/ , C3.CMMNS_CD_VALUE_NM AS GRADE_SE_CD /** 학년구분코드 **/ , C4.CMMNS_CD_VALUE_NM AS CNTCHT_APLCNT_TYPE_SE_CD /** 잇는채팅신청자 유형코드 **/ , C##RG.DEC_B64(AA.APLCNT_MBL_TELNO_ENCPT) AS APLCNT_CTTPC_TELNO /** 신청자연락처 **/ , AA.ITNEUN_CHTT_APLY_CS_DTL_CN AS ITNEUN_CHTT_APLY_CS_DTL_CN /** 상세내용 **/ , AA.DSCSN_EXPRNC_YN AS DSCSN_EXPRNC_YN /** 상담경험여부 **/ , AA.ETC_DSCSN_YN AS EXP1 , '○ 기타상담여부 ( ' || AA.ETC_DTL_CN || ' ) / ' AS EXP1_1 , AA.ETC_DSCSN_CONT_DTL_CN AS EXP1_2 , AA.LIAL_DSCSN_YN AS EXP2 , '○ 다들어줄게상담여부 / ' AS EXP2_1 , AA.LIAL_DSCSN_CONT_DTL_CN AS EXP2_2 , AA.CO13_YN AS EXP3 , '○ 1388상담여부 / ' AS EXP3_1 , AA.CO13_CONT_DTL_CN AS EXP3_2 , AA.PVTESB_DSCSN_CNTER_DSCSN_YN AS EXP4 , '○ 사설상담센터상담여부 / ' AS EXP4_1 , AA.PVTESB_DSCSN_CNTER_DSCSN_CONT_DTL_CN AS EXP4_2 , AA.HSPTL_DSCSN_YN AS EXP5 , '○ 병원상담여부 / ' AS EXP5_1 , AA.HSPTL_DSCSN_CONT_DTL_CN AS EXP5_2 , AA.SUNFLO_CNTER_DSCSN_YN AS EXP6 , '○ 해바라기센터상담여부 / ' AS EXP6_1 , AA.SUNFLO_CNTER_DSCSN_CONT_DTL_CN AS EXP6_2 , AA.RGN_CHIL_CNTER_DSCSN_YN AS EXP7 , '○ 지역아동센터상담여부 / ' AS EXP7_1 , AA.RGN_CHIL_CNTER_DSCSN_CONT_DTL_CN AS EXP7_2 , AA.MIND_HEALTH_WLFAR_CNTER_DSCSN_YN AS EXP8 , '○ 정신건강복지센터상담여부 / ' AS EXP8_1 , AA.MIND_HEALTH_WLFAR_CNTER_DSCSN_CONT_DTL_CN AS EXP8_2 , AA.YNGBGS_DSCSN_WLFAR_CNTER_DSCSN_YN AS EXP9 , '○ 청소년상담복지센터상담여부 / ' AS EXP9_1 , AA.YNGBGS_DSCSN_WLFAR_CNTER_DSCSN_CONT_DTL_CN AS EXP9_2 , AA.KOREA_YNGBGS_DSCSN_WLFAR_DI_DSCSN_YN AS EXP10 , '○ 한국청소년상담복지개발원상담여부 / ' AS EXP10_1 , AA.KOREA_YNGBGS_DSCSN_WLFAR_DI_DSCSN_CONT_DTL_CN AS EXP10_2 , AA.TLPHON_CO13_YN AS EXP11 , '○ 전화1388상담여부 / ' AS EXP11_1 , AA.TLPHON_CO13_CONT_DTL_CN AS EXP11_2 , AA.YNGBGS_CYBER_DSCSN_CNTER_DSCSN_YN AS EXP12 , '○ 청소년사이버상담센터상담여부 / ' AS EXP12_1 , AA.YNGBGS_CYBER_DSCSN_CNTER_DSCSN_CONT_DTL_CN AS EXP12_2 , AA.PRVC_CLCT_AGRE_YN AS PRVC_CLCT_AGRE_YN /** 개인정보제공동의여부 **/ , C##RG.DEC_B64(AA.AGT_NM_ENCPT) AS AGT_NM /** 법정대리인성명 **/ , C##RG.DEC_B64(AA.AGT_MBL_TELNO_ENCPT) AS AGT_MBL_TELNO /** 법정대리인연락처 **/ , AA.ITNEUN_CHTT_RCPT_INTRVW_MON_HR_CN AS ITNEUN_CHTT_RCPT_INTRVW_MON_HR_CN /** 잇는채팅접수면접월요일시간내용 **/ , AA.ITNEUN_CHTT_RCPT_INTRVW_TUES_HR_CN AS ITNEUN_CHTT_RCPT_INTRVW_TUES_HR_CN /** 잇는채팅접수면접화요일시간내용 **/ , AA.ITNEUN_CHTT_RCPT_INTRVW_WED_HR_CN AS ITNEUN_CHTT_RCPT_INTRVW_WED_HR_CN /** 잇는채팅접수면접수요일시간내용 **/ , AA.ITNEUN_CHTT_RCPT_INTRVW_THUR_HR_CN AS ITNEUN_CHTT_RCPT_INTRVW_THUR_HR_CN /** 잇는채팅접수면접목요일시간내용 **/ , AA.ITNEUN_CHTT_RCPT_INTRVW_FRI_HR_CN AS ITNEUN_CHTT_RCPT_INTRVW_FRI_HR_CN /** 잇는채팅접수면접금요일시간내용 **/ , AA.ITNEUN_CHTT_RCPT_INTRVW_SAT_HR_CN AS ITNEUN_CHTT_RCPT_INTRVW_SAT_HR_CN /** 잇는채팅접수면접토요일시간내용 **/ , AA.ITNEUN_CHTT_RCPT_INTRVW_SUN_HR_CN AS ITNEUN_CHTT_RCPT_INTRVW_SUN_HR_CN /** 잇는채팅접수면접일요일시간내용 **/ , REPLACE(AA.ITNEUN_CHTT_CHTT_DSCSN_MON_HR_CN,'Half',':30') AS ITNEUN_CHTT_CHTT_DSCSN_MON_HR_CN /** 잇는채팅채팅상담월요일시간내용 **/ , REPLACE(AA.ITNEUN_CHTT_CHTT_DSCSN_TUES_HR_CN,'Half',':30') AS ITNEUN_CHTT_CHTT_DSCSN_TUES_HR_CN /** 잇는채팅채팅상담화요일시간내용 **/ , REPLACE(AA.ITNEUN_CHTT_CHTT_DSCSN_WED_HR_CN,'Half',':30') AS ITNEUN_CHTT_CHTT_DSCSN_WED_HR_CN /** 잇는채팅채팅상담수요일시간내용 **/ , REPLACE(AA.ITNEUN_CHTT_CHTT_DSCSN_THUR_HR_CN,'Half',':30') AS ITNEUN_CHTT_CHTT_DSCSN_THUR_HR_CN /** 잇는채팅채팅상담목요일시간내용 **/ , REPLACE(AA.ITNEUN_CHTT_CHTT_DSCSN_FRI_HR_CN,'Half',':30') AS ITNEUN_CHTT_CHTT_DSCSN_FRI_HR_CN /** 잇는채팅채팅상담금요일시간내용 **/ , REPLACE(AA.ITNEUN_CHTT_CHTT_DSCSN_SAT_HR_CN,'Half',':30') AS ITNEUN_CHTT_CHTT_DSCSN_SAT_HR_CN /** 잇는채팅채팅상담토요일시간내용 **/ , REPLACE(AA.ITNEUN_CHTT_CHTT_DSCSN_SUN_HR_CN,'Half',':30') AS ITNEUN_CHTT_CHTT_DSCSN_SUN_HR_CN /** 잇는채팅채팅상담일요일시간내용 **/ , BB.CONSTT_ID AS CONSTT_ID /** 상담자아이디 **/ , BB.CONSTT_NM_ENCPT AS CONSTT_NM /** 상담자이름 **/
, CASE WHEN AA.NOW_AGE < 14 THEN 'Y' ELSE 'N' END AS AGT_AGRE_YN
FROM AYB140 AA , AYA150 BB , SAC100 C1 , SAC100 C2 , SAC100 C3 , SAC100 C4 WHERE 1=1 AND AA.INDEX_SN = #{indexSn} AND BB.DEL_YN (+) = 'N' AND BB.BBSCTT_TYPE_SE_CD (+) = '92' /** 게시글 유형구분코드(92 - 잇는채팅) **/ AND BB.BBSCTT_ESNTAL_NO (+) = AA.INDEX_SN AND C1.CMMNS_CD_ID (+) = 'SXDC_SE_CD' /* 성별구분코드 */ AND C1.CMMNS_CD_VALUE (+) = AA.SXDC_SE_CD AND C2.CMMNS_CD_ID (+) = 'ACBG_SE_CD' /* 학력구분코드 */ AND C2.CMMNS_CD_VALUE (+) = AA.ACBG_SE_CD AND C3.CMMNS_CD_ID (+) = 'GRADE_SE_CD' /* 학년구분코드 */ AND C3.CMMNS_CD_VALUE (+) = AA.GRADE_SE_CD AND C4.CMMNS_CD_ID (+) = 'CNTCHT_APLCNT_TYPE_SE_CD' /* 학년구분코드 */ AND C4.CMMNS_CD_VALUE (+) = AA.CNTCHT_APLCNT_TYPE_SE_CD
